  undo(): void;
}
class CommandRegistry {
  private map = new Map<string, () => Command>();
  register(name: string, factory: () => Command) { this.map.set(name, factory); }
  create(name: string, ctx: any): Command | null { const f = this.map.get(name); return f ? f() : null; }
}
